arguments.command:
cat > /tmp/repro.py <<'EOF'
import attr

try:
    @attr.s
    class MyClass:
        x: int = attr.ib(type=int)
except ValueError as e:
    print(f"Caught expected error: {e}")
    assert "for 'x'" in str(e)
    print("Repro successful")
else:
    print("No ValueError raised")
    raise AssertionError("ValueError was expected")
EOF
python3 /tmp/repro.py; echo EXIT=$?
